def longest_brute(a: list[int], k: int) -> int:
    best = 0
    for i in range(len(a)):
        s = 0
        for j in range(i, len(a)):
            s += a[j]
            if s == k:
                best = max(best, j - i + 1)
    return best

def longest_subarray_sum_k(a: list[int], k: int) -> int:
    first: dict[int, int] = {}
    pre = 0
    best = 0
    for i, x in enumerate(a):
        pre += x
        if pre == k:
            best = i + 1
        need = pre - k
        if need in first:
            best = max(best, i - first[need])
        if pre not in first:
            first[pre] = i
    return best
